      "course_id": 1,
      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company makes forecasts each quarter to decide how to optimize operations to meet expected demand. The company uses ML models to make these forecasts.<br/>An AI practitioner is writing a report about the trained ML models to provide transparency and explainability to company stakeholders.<br/>What should the AI practitioner include in the report to meet the transparency and explainability requirements?</p>",
      "mark": 1,
      "is_partially_correct": false,
      "question_type": "1",
      "difficulty_level": "0",
      "general_feedback": "<p>Correct Answer: B</p>",
