      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company wants to develop an educational game where users answer questions such as the following: \"A jar contains six red, four green, and three yellow marbles. What is the probability of choosing a green marble from the jar?\"<br/>Which solution meets these requirements with the LEAST operational overhead?</p>",
      "mark": 1,
      "is_partially_correct": false,
      "question_type": "1",
      "difficulty_level": "0",
      "general_feedback": "<p>Correct Answer: C</p>",
      "is_active": true,
      "answer_list": [
        {
          "question_answer_id": 1,
          "question_id": "#14",
          "answers": [
            {
              "choice": "<p>Use supervised learning to create a regression model that will predict probability.</p>",
              "correct": false,
              "feedback": ""
            },
            {
              "choice": "<p>Use reinforcement learning to train a model to return the probability.</p>",
              "correct": false,
              "feedback": ""
            },
            {
              "choice": "<p>Use code that will calculate probability by using simple rules and computations.</p>",
              "correct": true,
              "feedback": ""
            },
            {
              "choice": "<p>Use unsupervised learning to create a model that will estimate probability density.</p>",
              "correct": false,
              "feedback": ""
            }
          ]
        }
      ],
