      "course_id": 1,
      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company has petabytes of unlabeled customer data to use for an advertisement campaign. The company wants to classify its customers into tiers to advertise and promote the company's products.<br/>Which methodology should the company use to meet these requirements?</p>",
      "mark": 1,
      "is_partially_correct": false,
