      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company wants to use a large language model (LLM) on Amazon Bedrock for sentiment analysis. The company wants to classify the sentiment of text passages as positive or negative.<br/><br/>Which prompt engineering strategy meets these requirements?</p>",
