            {
              "choice": "<p>Inference</p>",
              "correct": true,
              "feedback": ""
            },
            {
              "choice": "<p>Model deployment</p>",
              "correct": false,
              "feedback": ""
            },
            {
              "choice": "<p>Bias correction</p>",
              "correct": false,
              "feedback": ""
            }
