      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>An AI practitioner is building a model to generate images of humans in various professions. The AI practitioner discovered that the input data is biased and that specific attributes affect the image generation and create bias in the model.<br/>Which technique will solve the problem?</p>",
      "mark": 1,
