      "question_text": "<p>A company wants to deploy a conversational chatbot to answer customer questions. The chatbot is based on a fine-tuned Amazon SageMaker JumpStart model. The application must comply with multiple regulatory frameworks.<br/>Which capabilities can the company show compliance for? (Choose two.)</p>",
