      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company is training a foundation model (FM). The company wants to increase the accuracy of the model up to a specific acceptance level.<br/>Which solution will meet these requirements?</p>",
      "mark": 1,
      "is_partially_correct": false,
