          "content": "B. Amazon Comprehend:<br>Amazon Comprehend is a fully managed natural language processing (NLP) service that can analyze text and determine sentiment, entities, key phrases, and language. For customer sentiment analysis based on written reviews, Amazon Comprehend provides built-in sentiment analysis that can classify text as positive, negative, or neutral.<br>D. Amazon Bedrock:<br>Amazon Bedrock is a service that provides access to various foundation models (FMs), which can be used to build and deploy AI-driven applications. For advanced natural language processing tasks like sentiment analysis, foundation models can be fine-tuned and applied to specific use cases, such as understanding customer sentiment in reviews. This is a more customizable and advanced option compared to pre-built solutions like Amazon Comprehend.",
