      "question_id": "#57",
      "topic_id": 1,
      "course_id": 1,
      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company has installed a security camera. The company uses an ML model to evaluate the security camera footage for potential thefts. The company has discovered that the model disproportionately flags people who are members of a specific ethnic group.<br/>Which type of bias is affecting the model output?</p>",
      "mark": 1,
      "is_partially_correct": false,
      "question_type": "1",
      "difficulty_level": "0",
      "general_feedback": "<p>Correct Answer: B</p>",
      "is_active": true,
      "answer_list": [
        {
          "question_answer_id": 1,
          "question_id": "#57",
          "answers": [
            {
              "choice": "<p>Measurement bias</p>",
              "correct": false,
              "feedback": ""
            },
            {
              "choice": "<p>Sampling bias</p>",
              "correct": true,
              "feedback": ""
            },
            {
              "choice": "<p>Observer bias</p>",
              "correct": false,
              "feedback": ""
            },
            {
              "choice": "<p>Confirmation bias</p>",
              "correct": false,
              "feedback": ""
            }
          ]
        }
      ],
      "topic_name": "Exam AWS Certified AI Practitioner AIF-C01 topic 1 question 57 discussion - ExamTopics",
      "discusstion": [
        {
          "id": 1592350,
          "date": "Thu 31 Jul 2025 04:32",
          "username": "65703c1",
          "content": "B is the correct answer",
          "upvote_count": "1",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1569483,
          "date": "Fri 16 May 2025 21:27",
          "username": "Rcosmos",
          "content": "O viés que está afetando a saída do modelo é B. Viés de amostragem.<br>Esse tipo de viés ocorre quando os dados usados para treinar o modelo não representam adequadamente a população real. No caso da câmera de segurança, se o conjunto de dados de treinamento contiver mais exemplos de pessoas de um grupo étnico sendo associadas a atividades suspeitas, o modelo pode aprender padrões distorcidos e aplicar essas associações de forma desproporcional, levando a discriminação injusta.<br>Os outros tipos de viés não se aplicam diretamente a esse cenário:",
          "upvote_count": "1",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1356353,
          "date": "Fri 14 Feb 2025 04:23",
          "username": "Willdoit",
          "content": "Sampling bias occurs when the data used to train the machine learning model is not representative of the entire population or the range of possible scenarios. If the model disproportionately flags people from a specific ethnic group, it suggests that the data used to train the model may have an overrepresentation or underrepresentation of certain ethnic groups, leading to biased predictions.",
          "upvote_count": "3",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1355392,
          "date": "Wed 12 Feb 2025 04:01",
          "username": "Jessiii",
          "content": "B. Sampling bias occurs when the data used to train the model is not representative of the entire population. In this case, if the training data contains an overrepresentation or underrepresentation of certain ethnic groups, the model may disproportionately flag individuals from specific ethnic groups, leading to biased outcomes.",
          "upvote_count": "2",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1354262,
          "date": "Mon 10 Feb 2025 06:34",
          "username": "pavankvv",
          "content": "Measurement bias occurs when the data used to train the machine learning model contains inherent biases or inaccuracies, leading to biased outputs or predictions.<br>In the given scenario, the security camera model is disproportionately flagging people from a specific ethnic group",
          "upvote_count": "1",
          "selected_answers": "Selected Answer:A"
        },
        {
          "id": 1335050,
          "date": "Tue 31 Dec 2024 23:05",
          "username": "Moon",
          "content": "B: Sampling bias<br>Explanation:<br>Sampling bias occurs when the training data used for an ML model is not representative of the real-world population. In this case, the model disproportionately flags members of a specific ethnic group, likely because the training dataset was not balanced or representative of all groups. This leads to skewed predictions that unfairly target certain populations.",
          "upvote_count": "2",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1333087,
          "date": "Sat 28 Dec 2024 18:53",
          "username": "RightAnswers",
          "content": "Sampling bias: occurs when the data used to train the ML model is not representative of the overall population, leading to the model performing poorly on certain groups, like in this case where the model is disproportionately flagging people from a specific ethnic group.<br>Why the other options are not correct:<br>Measurement bias:<br>This refers to errors in the way data is collected or measured, which isn't directly related to the ethnic group bias in this scenario.<br>Observer bias:<br>This happens when a human observer's personal biases influence their interpretation of data, which isn't applicable here as the model is making the evaluations automatically.<br>Confirmation bias:<br>This refers to the tendency to seek out information that confirms existing beliefs, which isn't relevant to the training data used to develop the ML model.",
          "upvote_count": "3",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1324284,
          "date": "Tue 10 Dec 2024 01:33",
          "username": "eesa",
          "content": "B. Sampling bias<br>Explanation:<br>Sampling bias occurs when the data used to train a model does not accurately represent the diversity of the population or real-world scenarios the model will encounter. In this case, if the training data for the security camera footage had an overrepresentation or underrepresentation of certain ethnic groups, the model may disproportionately flag members of that group as potential theft suspects. This leads to biased predictions due to imbalanced or unrepresentative training data.",
          "upvote_count": "1",
          "selected_answers": "Selected Answer:B"
        },
        {
          "id": 1322385,
          "date": "Thu 05 Dec 2024 15:28",
          "username": "aws4myself",
          "content": "A. Measurement bias<br>Measurement bias occurs when the measurement process itself is flawed, leading to systematic errors. In this case, the model is likely biased due to the way it's trained on data that may not be representative of the entire population. This can lead to the model incorrectly associating certain characteristics with criminal behavior, particularly for individuals from underrepresented groups.",
          "upvote_count": "1",
          "selected_answers": "Selected Answer:A"
        },
        {
          "id": 1310598,
          "date": "Tue 12 Nov 2024 14:19",
          "username": "Blair77",
          "content": "B - Sampling bias occurs when the data used to train a model is not representative of the population or real-world scenarios it's meant to analyze. This leads to skewed results that favor or disfavor certain groups.",
          "upvote_count": "4",
          "selected_answers": "Selected Answer:B"
        }
      ]
