          "date": "Wed 23 Apr 2025 18:27",
          "username": "Rcosmos",
          "content": "Explicação: A transformação em lote (batch transform) do Amazon SageMaker é ideal quando: Você precisa realizar inferência em grandes volumes de dados (vários GBs),<br>Não há necessidade de resposta em tempo real, Os dados estão arquivados (por exemplo, em Amazon S3), O processamento pode ocorrer de forma agendada ou sob demanda, com resultados também armazenados em lote. Essa abordagem é eficiente, escalável e econômica para casos em que a latência não é um fator crítico.<br>D. Inferência assíncrona<br>➡️ Boa para requisições grandes com latência variável, mas ainda envolve chamadas via endpoint.<br>Batch transform é mais otimizado quando os dados já estão arquivados e processados em massa.",
