          "content": "A. Amazon Textract: Amazon Textract is a fully managed service that automatically extracts text and data from scanned documents, including PDFs. It uses machine learning to identify the text in the document and converts it into a plain-text format, making it ideal for converting resumes from PDF to text for further processing.",
