      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company is using domain-specific models. The company wants to avoid creating new models from the beginning. The company instead wants to adapt pre-trained models to create models for new, related tasks.<br/>Which ML strategy meets these requirements?</p>",
