          "username": "Jessiii",
          "content": "C. Exploratory data analysis (EDA): EDA is the process of analyzing and visualizing the data to understand its characteristics and identify patterns, relationships, and anomalies. The company is performing actions like creating a correlation matrix, calculating statistics, and visualizing the data, all of which are typical activities in EDA.",
