      "question_text": "<p>A large retailer receives thousands of customer support inquiries about products every day. The customer support inquiries need to be processed and responded to quickly. The company wants to implement Agents for Amazon Bedrock.<br/>What are the key benefits of using Amazon Bedrock agents that could help this retailer?</p>",
