          "content": "A. Generation of custom foundation models (FMs) to predict customer needs<br>While creating custom FMs could be valuable for tailored predictions, Amazon Bedrock agents themselves focus on automating workflows and orchestrating the use of multiple FMs, rather than creating custom models.<br>B. Automation of repetitive tasks and orchestration of complex workflows<br>This is a strong benefit of Amazon Bedrock agents, but option C more directly addresses the use case of consolidating results from multiple FMs to handle customer inquiries.<br>D. Selecting the foundation model (FM) based on predefined criteria and metrics<br>While selecting models based on criteria is possible, the primary strength of Bedrock agents in this context is in automating the calling of multiple models and consolidating their responses.",
