      "course_id": 1,
      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>An ML research team develops custom ML models. The model artifacts are shared with other teams for integration into products and services. The ML team retains the model training code and data. The ML team wants to build a mechanism that the ML team can use to audit models.<br/><br/>Which solution should the ML team use when publishing the custom ML models?</p>",
