      "case_study_id": null,
      "lab_id": 0,
      "question_text": "<p>A company is using Retrieval Augmented Generation (RAG) with Amazon Bedrock and Stable Diffusion to generate product images based on text descriptions. The results are often random and lack specific details. The company wants to increase the specificity of the generated images.<br/><br/>Which solution meets these requirements?</p>",
