          "content": "In Stable Diffusion, Classifier-Free Guidance (CFG) scale controls how strongly the model follows the text prompt versus generating freely (more randomness).<br>A higher CFG scale means the model adheres more closely to the prompt, resulting in more specific and detailed images.<br>A lower CFG scale introduces more randomness, leading to less relevant or vague outputs.",
